    private func name(_ bytes: [UInt8]) -> String { String(decoding: bytes, as: UTF8.self) }

    private func file(_ name: String, _ size: Int64, fileID: UInt64, links: UInt32 = 1, clone: UInt64 = 0,
                      shared: Bool = false) -> ScanEntry {
        ScanEntry(name: name, isDirectory: false, allocSize: size, logicalSize: size - 3, fileID: fileID,
                  linkCount: links, cloneID: clone, sharesAllBlocks: shared, modTime: 1_700_000_000 + Int64(fileID),
                  accessTime: 1_700_100_000 + Int64(fileID), device: 3)
    }

    private func dir(_ name: String, fileID: UInt64) -> ScanEntry {
        ScanEntry(name: name, isDirectory: true, fileID: fileID, modTime: 1_600_000_000 + Int64(fileID), device: 3)
    }

    /// 40 B, NFD, 15 B and 16 B names; a hardlink pair, a clone pair, a removed subtree, and partial,
    /// unavailable and listingIncomplete folders.
    private func goldenTree() -> FileTree {
        let t = FileTree(rootPath: "/golden", device: 3, rootModTime: 1_500_000_000)
        let a = t.addChild(of: FileTree.root, entry: dir("a", fileID: 10))
        let nested = t.addChild(of: a, entry: dir("nested", fileID: 11))
        let gone = t.addChild(of: FileTree.root, entry: dir("gone", fileID: 12))
        t.addChild(of: gone, entry: file("dead", 5000, fileID: 13))
        let b = t.addChild(of: FileTree.root, entry: dir("b", fileID: 14))
        t.addChild(of: nested, entry: file("h1", 4096, fileID: 17, links: 2))
        t.addChild(of: b, entry: file("h2", 4096, fileID: 17, links: 2))
        t.addChild(of: nested, entry: file("c1", 8192, fileID: 18, clone: 42, shared: true))
        t.addChild(of: b, entry: file("c2", 8192, fileID: 19, clone: 42, shared: true))
        t.addChild(of: a, entry: file(name(Array("a-forty-byte-name-for-the-golden-file.tx".utf8)), 300, fileID: 20))
        t.addChild(of: a, entry: file(name(Array("cafe".utf8) + [0xCC, 0x81] + Array("-nfd.txt".utf8)), 200, fileID: 21))
        t.addChild(of: b, entry: file(name(Array("fifteen-bytes.t".utf8)), 15, fileID: 22))
        t.addChild(of: b, entry: file(name(Array("sixteen-bytes.tx".utf8)), 16, fileID: 23))
        let p = t.addChild(of: FileTree.root, entry: dir("p", fileID: 24))
        t.addChild(of: p, entry: file("inside", 700, fileID: 25))
        let u = t.addChild(of: FileTree.root, entry: dir("u", fileID: 26))
        t.recomputeAggregates()
        t.markListingIncomplete(p)
        t.markUnavailable(u)
        t.removeSubtree(gone)
        return t
    }

    private func blobStart(_ bytes: [UInt8]) -> Int {
        12 + (0..<4).reduce(0) { $0 | Int(bytes[8 + $1]) << (8 * $1) }
    }

    private func temporaryURL() throws -> URL {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        addTeardownBlock { try? FileManager.default.removeItem(at: dir) }
        return dir.appendingPathComponent("tree.dscan")
    }

    func testGoldenV2ReadsAndRewritesIdentically() throws {
        let url = try temporaryURL()
        let fresh = goldenTree()
        XCTAssertEqual(fresh.nodes.map { $0.name.utf8.count }.filter { $0 == 40 }.count, 1)
        try Snapshot.writeUncompressed(fresh, meta: Self.goldenMeta, to: url)
        let written = [UInt8](try Data(contentsOf: url))
        if ProcessInfo.processInfo.environment["HOARD_PRINT_GOLDEN"] == "1" {
            var lines: [String] = []
            for start in stride(from: 0, to: written.count, by: 16) {
                let row = written[start..<min(start + 16, written.count)]
                lines.append("        " + row.map { String(format: "0x%02X,", $0) }.joined(separator: " "))
            }
            print("GOLDEN-BEGIN\n" + lines.joined(separator: "\n") + "\nGOLDEN-END")
        }

        // The writer still produces the golden bytes after the meta block.
        let golden = Self.golden
        XCTAssertFalse(golden.isEmpty)
        guard !golden.isEmpty else { return }
        XCTAssertEqual(Array(written[blobStart(written)...]), Array(golden[blobStart(golden)...]))

        // The golden file still reads, with the same meta, paths, totals, flags and statuses.
        try Data(golden).write(to: url)
        let (restored, meta) = try Snapshot.read(from: url)
        var expectedMeta = Self.goldenMeta
        expectedMeta.formatVersion = 2
        XCTAssertEqual(meta, expectedMeta)
        let livePaths = fresh.nodes.indices.filter { !fresh.nodes[$0].isRemoved }.map { fresh.path(of: NodeID($0)) }
        XCTAssertEqual(restored.nodeCount, 15)
        XCTAssertEqual(restored.nodes.indices.map { restored.path(of: NodeID($0)) }, livePaths)
        for i in fresh.nodes.indices where !fresh.nodes[i].isRemoved {
            let path = fresh.path(of: NodeID(i))
            let id = try XCTUnwrap(restored.lookup(path: path), path)
            var expected = fresh[NodeID(i)]
            expected.parent = restored[id].parent
            expected.firstChild = restored[id].firstChild
            expected.nextSibling = restored[id].nextSibling
            XCTAssertEqual(restored[id], expected, path)
            XCTAssertTrue(restored[id].name.utf8.elementsEqual(fresh[NodeID(i)].name.utf8), path)
        }
        let root = restored[FileTree.root]
        XCTAssertEqual(root.totalAlloc, 4096 + 8192 + 300 + 200 + 15 + 16 + 700)
        XCTAssertEqual(root.fileCount, 9)
        XCTAssertEqual(root.dirCount, 6)
        XCTAssertEqual(root.status, .partial)
        func node(_ path: String) throws -> Node { restored[try XCTUnwrap(restored.lookup(path: path), path)] }
        XCTAssertEqual(try node("/golden/p").status, .partial)
        XCTAssertTrue(try node("/golden/p").flags.contains(.listingIncomplete))
        XCTAssertEqual(try node("/golden/u").status, .unavailable)
        XCTAssertNil(restored.lookup(path: "/golden/gone"))
        XCTAssertEqual([try node("/golden/a/nested/h1"), try node("/golden/b/h2")].filter { $0.flags.contains(.duplicate) }.count, 1)
        XCTAssertEqual([try node("/golden/a/nested/c1"), try node("/golden/b/c2")].filter { $0.flags.contains(.duplicate) }.count, 1)
        XCTAssertTrue(try node("/golden/a/nested/c1").flags.contains(.cloneShared))
        XCTAssertEqual(try node("/golden/a").totalAlloc, 4096 + 8192 + 300 + 200)
        XCTAssertEqual(try node("/golden/b").totalAlloc, 15 + 16)
    }

    func testInvalidUTF8NameThrows() throws {
        let url = try temporaryURL()
        let t = FileTree(rootPath: "/bad", device: 1)
        let d = t.addChild(of: FileTree.root, entry: ScanEntry(name: "d", isDirectory: true, device: 1))
        t.addChild(of: d, entry: ScanEntry(name: "short.txt", isDirectory: false, allocSize: 1, device: 1))
        let unique = name(Array("unique-forty-byte-name-at-the-blob-end.x".utf8))
        XCTAssertEqual(unique.utf8.count, 40)
        t.addChild(of: d, entry: ScanEntry(name: unique, isDirectory: false, allocSize: 2, device: 1))
        t.recomputeAggregates()
        try Snapshot.writeUncompressed(t, meta: SnapshotMeta(rootPath: "/bad", device: 1, createdAt: Date(timeIntervalSinceReferenceDate: 0),
                                                 scanSeconds: 0, lastEventId: 0, eventsUUID: nil), to: url)
        var bytes = [UInt8](try Data(contentsOf: url))
        XCTAssertNoThrow(try Snapshot.read(from: url))
        let jsonLength = blobStart(bytes) - 12
        let nameLength = (0..<4).reduce(0) { $0 | Int(bytes[16 + jsonLength + $1]) << (8 * $1) }
        let last = 20 + jsonLength + nameLength - 1
        XCTAssertEqual(bytes[last], UInt8(ascii: "x"))
        bytes[last] = 0xFF
        try Data(bytes).write(to: url)
        XCTAssertThrowsError(try Snapshot.read(from: url)) { XCTAssertEqual($0 as? SnapshotError, .truncated) }
    }
}
